package com.nook.controller; import com.nook.domain.SocialEntities.AuthProvider; import com.nook.dto.ApiDtos.*; import com.nook.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/auth") public class AuthController {final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) Token register(@Valid @RequestBody Register x){return service.register(x);}@PostMapping("/login") Token login(@Valid @RequestBody Login x){return service.login(x);}@PostMapping("/apple") Token apple(@Valid @RequestBody FederatedAuth x){return service.federated(AuthProvider.APPLE,x);}@PostMapping("/google") Token google(@Valid @RequestBody FederatedAuth x){return service.federated(AuthProvider.GOOGLE,x);}@PostMapping("/facebook") Token facebook(@Valid @RequestBody FederatedAuth x){return service.federated(AuthProvider.FACEBOOK,x);}@PostMapping("/phone/request-code") PhoneOtpRequested requestPhone(@Valid @RequestBody PhoneOtpRequest x){return service.requestPhoneOtp(x.phone());}@PostMapping("/phone/verify-code") Token verifyPhone(@Valid @RequestBody PhoneOtpVerify x){return service.verifyPhoneOtp(x);}@PostMapping("/refresh") Token refresh(@Valid @RequestBody Refresh x){return service.refresh(x.refreshToken());}@PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) void logout(@Valid @RequestBody Refresh x){service.logout(x.refreshToken());}}
